export const CBS_DB_ERRORS: CbsDbError[] = [

    {

      code: 'ORA-00054',
      name: 'resource busy and acquire with NOWAIT specified or timeout expired',
      engine: 'Oracle',
      severity: 'HIGH',
      symptom: 'Une mise à jour batch ou une transaction en ligne échoue immédiatement car la ressource ou la table est déjà verrouillée en mode exclusif.',
      rootCause: 'Une session concurrente a verrouillé une ou plusieurs lignes (SELECT FOR UPDATE) ou la table entière (ALTER TABLE, DDL, LOCK TABLE), et la requête demanderesse utilise NOWAIT.',
      diagnosticQueries: [
        'SELECT s.sid, s.serial#, s.username, s.osuser, s.program, s.status, l.type, l.lmode, l.request FROM v\$session s JOIN v\$lock l ON s.sid = l.sid WHERE l.block = 1;',
        'SELECT o.object_name, s.sid, s.serial#, s.machine, s.action FROM v\$locked_object lo JOIN dba_objects o ON lo.object_id = o.object_id JOIN v\$session s ON lo.session_id = s.sid;',
      ],
      resolutionSteps: [
        '1. Identifier la session bloquante via v\$session et v\$locked_object.',
        '2. Contacter l\'utilisateur ou vérifier le batch coupable (souvent une session SQL Developer ou un batch 4GL resté ouvert sans COMMIT).',
        '3. Si la session est orpheline ou inactive : ALTER SYSTEM KILL SESSION \'sid,serial#\' IMMEDIATE;',
        '4. Relancer la transaction ou le step de traitement.',
      ],
      prevention: 'Toujours poser des COMMIT réguliers dans les batchs PL/SQL ou 4GL et interdire les verrous exclusifs en pleine journée de production.',
    },
{

      code: 'ORA-00060',
      name: 'deadlock detected while waiting for resource',
      engine: 'Oracle',
      severity: 'CRITICAL',
      symptom: 'Une transaction est brutalement annulée avec l\'erreur ORA-00060 dans les logs applicatifs. Un fichier trace d\'alerte (alert.log) est généré.',
      rootCause: 'Interblocage mutuel (Deadlock) : la session A détient le verrou sur la ressource 1 et attend la ressource 2, tandis que la session B détient la ressource 2 et attend la ressource 1. Oracle tranche en tuant l\'un des deux processus.',
      diagnosticQueries: [
        'SELECT to_char(originating_timestamp, \'YYYY-MM-DD HH24:MI:SS\'), message_text FROM v\$diag_alert_ext WHERE message_text LIKE \'%ORA-00060%\';',
        'Consulter le fichier .trc généré dans le répertoire trace (show parameter user_dump_dest ou ADR Home).',
      ],
      resolutionSteps: [
        '1. Examiner le fichier trace (.trc) identifiant les 2 requêtes SQL et les 2 lignes impliquées.',
        '2. Déterminer si le problème provient d\'un manque d\'index sur une clé étrangère (cause très fréquente d\'interblocage de table enfant).',
        '3. Revoir l\'ordre de mise à jour des tables dans les programmes applicatifs pour garantir un ordre strict et uniforme (ex: toujours verrouiller BKCLI puis BKCPT).',
      ],
      prevention: 'Indexer systématiquement toutes les clés étrangères (Foreign Keys) et ordonner rigoureusement les ordres UPDATE dans le code PL/SQL et 4GL.',
    },
{

      code: 'ORA-01555',
      name: 'snapshot too old: rollback segment number with name too small',
      engine: 'Oracle',
      severity: 'HIGH',
      symptom: 'Un traitement batch long (ex: calcul d\'intérêts EOD, extraction comptable) plante après plusieurs heures d\'exécution.',
      rootCause: 'Le curseur de lecture a démarré à l\'instant T0. Des transactions concurrentes ont modifié les blocs de données et fait des COMMIT. Les images avant modification (Undo data) ont été écrasées dans les segments d\'annulation car UNDO_RETENTION ou la taille du tablespace UNDO était insuffisante.',
      diagnosticQueries: [
        'SELECT * FROM v\$undostat ORDER BY begin_time DESC FETCH FIRST 10 ROWS ONLY;',
        'SHOW PARAMETER undo_retention;',
        'SELECT tablespace_name, sum(bytes)/1024/1024/1024 as GB_FREE FROM dba_free_space WHERE tablespace_name LIKE \'%UNDO%\' GROUP BY tablespace_name;',
      ],
      resolutionSteps: [
        '1. Augmenter le paramètre UNDO_RETENTION : ALTER SYSTEM SET undo_retention = 28800 SCOPE=BOTH; (ex: 8 heures).',
        '2. Si nécessaire, augmenter la taille du tablespace UNDO (AUTOEXTEND ON MAXSIZE ...).',
        '3. Optimiser la requête SQL pour réduire son temps d\'exécution (éviter le Full Table Scan sur des tables à plusieurs millions de lignes).',
        '4. Relancer le batch après libération ou redimensionnement.',
      ],
      prevention: 'Ne pas faire de COMMIT dans une boucle de curseur fetchant la même table (Fetch across commit) et calibrer l\'UNDO pour couvrir la plus longue requête EOD.',
    },
{

      code: 'ORA-00942',
      name: 'table or view does not exist',
      engine: 'Oracle',
      severity: 'MEDIUM',
      symptom: 'Un programme 4GL, script shell ou requête batch ne compile pas ou échoue à l\'exécution.',
      rootCause: 'La table demandée n\'existe pas sous le schéma courant, le synonyme public/privé est manquant, ou l\'utilisateur connecté n\'a pas reçu le privilège SELECT/UPDATE sur la table du propriétaire (ex: BKOWNER.BKCPT).',
      diagnosticQueries: [
        'SELECT owner, object_name, object_type FROM all_objects WHERE object_name = UPPER(\'NOM_TABLE\');',
        'SELECT * FROM all_tab_privs WHERE table_name = UPPER(\'NOM_TABLE\');',
        'SELECT * FROM all_synonyms WHERE synonym_name = UPPER(\'NOM_TABLE\');',
      ],
      resolutionSteps: [
        '1. Vérifier si le préfixe du schéma est requis (ex: BKOWNER.BKCPT).',
        '2. Vérifier les droits : GRANT SELECT, INSERT, UPDATE, DELETE ON BKOWNER.BKCPT TO UTILISATEUR;',
        '3. Créer le synonyme si nécessaire : CREATE SYNONYM UTILISATEUR.BKCPT FOR BKOWNER.BKCPT;',
      ],
      prevention: 'Vérifier la livraison des scripts de migration DDL avant la mise en recette ou en production.',
    },
{

      code: 'ORA-01400',
      name: 'cannot insert NULL into (string.string.string)',
      engine: 'Oracle',
      severity: 'MEDIUM',
      symptom: 'Échec d\'une écriture en base (INSERT) lors d\'une saisie ou de l\'intégration d\'un fichier d\'interface.',
      rootCause: 'Tentative d\'insertion d\'une valeur nulle dans une colonne configurée avec la contrainte NOT NULL.',
      diagnosticQueries: [
        'SELECT column_name, nullable, data_type FROM all_tab_columns WHERE table_name = UPPER(\'NOM_TABLE\') AND column_name = UPPER(\'NOM_COLONNE\');',
      ],
      resolutionSteps: [
        '1. Inspecter le payload ou la ligne du fichier d\'interface qui a causé l\'erreur.',
        '2. Si la valeur nulle est anormale, corriger le fichier d\'entrée ou le mapping applicatif.',
        '3. Si la colonne peut légitimement être vide, modifier la contrainte en base après validation métier : ALTER TABLE NOM_TABLE MODIFY NOM_COLONNE NULL;',
      ],
      prevention: 'Mettre en place une validation des champs obligatoires en amont au niveau des interfaces applicatives (API / Parsing).',
    },
{

      code: 'ORA-12514 / ORA-12154',
      name: 'TNS:listener does not currently know of service / could not resolve connect identifier',
      engine: 'Oracle',
      severity: 'CRITICAL',
      symptom: 'Impossible pour les serveurs applicatifs Amplitude (AIX / Linux) ou les postes clients de se connecter à la base Oracle.',
      rootCause: 'Le listener Oracle n\'a pas encore enregistré le service de la base, le nom du service dans tnsnames.ora est erroné, ou le listener est arrêté.',
      diagnosticQueries: [
        'Sur le serveur DB : lsnrctl status',
        'Sur le serveur APP : tnsping <NOM_SERVICE_TNS>',
        'Vérifier le fichier \$ORACLE_HOME/network/admin/tnsnames.ora',
      ],
      resolutionSteps: [
        '1. Vérifier l\'état du listener sur le serveur DB : lsnrctl status [LISTENER_NAME].',
        '2. Si le listener est arrêté : lsnrctl start.',
        '3. Si le service est inconnu : vérifier la base : sqlplus / as sysdba -> ALTER SYSTEM REGISTER;',
        '4. Vérifier la syntaxe du tnsnames.ora sur le serveur applicatif.',
      ],
      prevention: 'Surveiller le port listener (1521) par un agent de monitoring et maintenir un tnsnames.ora versionné.',
    },
{

      code: 'INFORMIX-244',
      name: 'Could not do a physical-order read to fetch next row (Lock timeout)',
      engine: 'Informix',
      severity: 'HIGH',
      symptom: 'Blocage lors de la lecture d\'une table par un programme 4GL ou dbaccess.',
      rootCause: 'Une autre session verrouille la ligne ou la page de données, et l\'isolation level est en WAIT insuffisant ou la session est bloquée en mode exclusif.',
      diagnosticQueries: [
        'onstat -k : Liste tous les verrous actifs en mémoire Informix.',
        'onstat -u : Affiche les sessions utilisatrices et leur statut.',
        'onstat -g ses <session_id> : Détails d\'une session bloquante.',
      ],
      resolutionSteps: [
        '1. Exécuter SET LOCK MODE TO WAIT 30; dans le programme 4GL ou la session dbaccess.',
        '2. Identifier la session tenant le verrou via onstat -k et onstat -u.',
        '3. Terminer la session orpheline si nécessaire via onmode -z <session_id>.',
      ],
      prevention: 'Configurer les programmes Informix 4GL avec SET ISOLATION TO DIRTY READ quand la lecture seule le permet.',
    },

];

